import{_ as t,o as a,c as l,a2 as i}from"./chunks/framework.C-si7TFR.js";const p=JSON.parse('{"title":"公共与专属技能","description":"","frontmatter":{"title":"公共与专属技能"},"headers":[],"relativePath":"zh/guide/skills.md","filePath":"zh/guide/skills.md"}'),n={name:"zh/guide/skills.md"};function o(r,e,s,h,d,g){return a(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="公共与专属技能" tabindex="-1">公共与专属技能 <a class="header-anchor" href="#公共与专属技能" aria-label="Permalink to &quot;公共与专属技能&quot;">​</a></h1><p>技能为 Agent 提供完成某类任务的方法和操作约定；它不等同于 MCP 工具，也不会替代模型配置。</p><h2 id="公共技能" tabindex="-1">公共技能 <a class="header-anchor" href="#公共技能" aria-label="Permalink to &quot;公共技能&quot;">​</a></h2><p>公共技能面向多个 Agent 复用。</p><ol><li>从工作台的技能市场或管理入口选择<strong>新建技能</strong>。</li><li>填写名称和用途，上传 <code>SKILL.md</code> 或按界面方式添加内容。</li><li>在 Agent 配置的技能区域勾选需要的公共技能。</li><li>保存 Agent，用一个符合技能用途的任务验证结果。</li></ol><p>修改公共技能可能影响多个 Agent。发布前检查适用范围，避免将项目秘密、账号或个人数据写入公共内容。</p><h2 id="agent-专属技能" tabindex="-1">Agent 专属技能 <a class="header-anchor" href="#agent-专属技能" aria-label="Permalink to &quot;Agent 专属技能&quot;">​</a></h2><p>在目标 Agent 的<strong>专属技能</strong>区域新建或管理。每个专属技能有名称、描述、提示词、资源文件和工具绑定，工具绑定包含内置工具与工作流工具。</p><ul><li><strong>提示词</strong>描述该 Agent 在特定任务中应遵循的方法。</li><li><strong>资源文件</strong>提供该技能所需资料，应检查大小、内容和敏感信息。</li><li><strong>工具绑定</strong>决定可执行能力，不是添加一段提示词就自动获得权限。</li></ul><p>公共与专属同名时，专属版本优先；不要利用同名覆盖来绕过公共内容审查。</p><h2 id="选择技能还是工具" tabindex="-1">选择技能还是工具 <a class="header-anchor" href="#选择技能还是工具" aria-label="Permalink to &quot;选择技能还是工具&quot;">​</a></h2><ul><li>需要“告诉 Agent 怎么做”：优先技能。</li><li>需要“让 Agent 调用外部系统”：优先 <a href="./mcp-tools.html">MCP 工具</a>。</li><li>需要“严格执行固定步骤”：优先<a href="./workflows.html">工作流</a>。</li><li>需要“检索内部文档”：优先<a href="./knowledge.html">知识库</a>。</li></ul><p>删除技能前检查 Agent 引用。技能修改后用一个明确的成功标准验证，而不是只检查名称是否保存。</p>',13)])])}const _=t(n,[["render",o]]);export{p as __pageData,_ as default};
